values
  ('fbd97280-ebdd-5723-a4b8-8290d875d150', null, (select id from public.skills where slug = 'read-g8-argument-evidence'), null, 'hard',
   $q$Which of Moreau's points gave the council the strongest reason to be cautious, and why?$q$, $q$[{"text":"The harm to horses' eyes, because it was the most surprising claim made during the debate.","is_correct":false,"misconception_token":"confuses-surprise-with-strength"},{"text":"The cost of the gas lamps, because Moreau proved they were cheaper to run.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Fenwick's short time in Millbrook, because newer residents usually make poor decisions.","is_correct":false,"misconception_token":"accepts-irrelevant-evidence"},{"text":"The company's lack of experience, because it was a stated fact that connected directly to the risk of broken lights.","is_correct":true}]$q$::jsonb, $q$The company's lack of experience, because it was a stated fact that connected directly to the risk of broken lights.$q$, $q$A company "formed only four months earlier" that "had never built a lighting system" is a relevant, factual risk, and the council's test plan answers exactly that concern. The horse claim had no evidence behind it, so it was Moreau's weakest point.$q$, 'draft', '1320f481-cf9c-5b60-9035-011cd5957c22')
