  ('1628780f-e199-5bfd-9605-9ae9f9c52a62', null, (select id from public.skills where slug = 'read-g8-argument-evidence'), null, 'hard',
   $q$What is the main problem with the reasoning in the sentence "If students can fix laptops, they will all become engineers someday"?$q$, $q$[{"text":"It jumps to a sweeping conclusion that no evidence in the passage supports.","is_correct":true},{"text":"It relies too heavily on the results from Lakeview Middle School.","is_correct":false,"misconception_token":"misidentifies-flaw"},{"text":"It answers a counterclaim that the author never introduced.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It repeats the cost evidence that the author already gave earlier.","is_correct":false,"misconception_token":"misreads-structure"}]$q$::jsonb, $q$It jumps to a sweeping conclusion that no evidence in the passage supports.$q$, $q$Nothing in the passage shows that repair skills lead every student into engineering, so "they will all" is an overstatement. The Lakeview results are about saved money and faster repairs, not about careers, so the sentence does not rely on them.$q$, 'draft', '815f9064-82a4-59f7-849f-883751b4ae79')
